CREATE TABLE stores(store_id INT PRIMARY KEY,store_name VARCHAR(100),city VARCHAR(50),state VARCHAR(50),store_type VARCHAR(30),opening_date DATE,packing_station_count INT);
CREATE TABLE products(product_id INT PRIMARY KEY,sku_code VARCHAR(50) UNIQUE,product_name VARCHAR(150),category VARCHAR(50),subcategory VARCHAR(50),brand VARCHAR(100),unit_price NUMERIC(10,2),unit_cost NUMERIC(10,2),unit_weight_kg NUMERIC(10,3),shelf_life_days INT);
CREATE TABLE orders(order_id BIGINT PRIMARY KEY,store_id INT REFERENCES stores,customer_id BIGINT,order_datetime TIMESTAMP,order_status VARCHAR(30),order_created_at TIMESTAMP,picking_started_at TIMESTAMP,picking_completed_at TIMESTAMP,packed_at TIMESTAMP,dispatched_at TIMESTAMP);
CREATE TABLE order_items(order_item_id BIGINT PRIMARY KEY,order_id BIGINT REFERENCES orders,product_id INT REFERENCES products,quantity INT,unit_price NUMERIC(10,2));
CREATE TABLE inventory(inventory_id BIGINT PRIMARY KEY,store_id INT REFERENCES stores,product_id INT REFERENCES products,inventory_date DATE,stock_qty INT,reorder_level INT,stockout_flag BOOLEAN);
CREATE TABLE store_layout(location_id BIGINT PRIMARY KEY,store_id INT REFERENCES stores,product_id INT REFERENCES products,aisle_id VARCHAR(20),shelf_id VARCHAR(20),rack_position VARCHAR(20),zone VARCHAR(50),distance_from_packing_m NUMERIC(10,2));
CREATE TABLE picking_logs(picking_id BIGINT PRIMARY KEY,order_id BIGINT REFERENCES orders,picker_id INT,store_id INT REFERENCES stores,product_id INT REFERENCES products,aisle_id VARCHAR(20),pick_start_time TIMESTAMP,pick_end_time TIMESTAMP,quantity_picked INT,distance_travelled_m NUMERIC(10,2));
CREATE TABLE dispatch_logs(dispatch_id BIGINT PRIMARY KEY,order_id BIGINT REFERENCES orders,store_id INT REFERENCES stores,rider_id INT,rider_assigned_at TIMESTAMP,rider_arrived_at TIMESTAMP,dispatch_time TIMESTAMP,delivery_deadline TIMESTAMP);
